<script setup lang="ts">
import Modal from "@papilio/ui/Modal.vue";
import { computed, onMounted, ref, watch } from "vue";
import { useAuth, useResellerAuth } from "@papilio/auth";
import { item, query, request, type Page, type ResellerAccount, type ResellerAccountChange, type StaffScopeCatalog } from "@papilio/api";
import { faNumber } from "@papilio/ui";
import StaffScopeEditor from "./StaffScopeEditor.vue";
import { useI18n } from "vue-i18n";
import { useLocalizedFormats } from "../composables/useLocalizedFormats";
const props=defineProps<{resellerId?:number;realm:"admin"|"reseller"}>();
const staff=useAuth(), reseller=useResellerAuth(), {t}=useI18n(), {date}=useLocalizedFormats();
const base=computed(()=>props.realm==="admin"?`/v1/admin/resellers/${props.resellerId}/accounts`:"/v1/reseller/accounts");
const catalog=ref<StaffScopeCatalog|null>(null), rows=ref<ResellerAccount[]>([]), selected=ref<ResellerAccount|null>(null);
const page=ref(1),pages=ref(1),total=ref(0),q=ref(""),loading=ref(false),busy=ref(false),error=ref(""),notice=ref("");
const scopes=ref<string[]>([]),active=ref(false),reason=ref(""),password=ref(""),passwordReason=ref("");
const username=ref(""),newPassword=ref(""),newScopes=ref<string[]>([]),newActive=ref<""|"true"|"false">("");
const history=ref<ResellerAccountChange[]>([]),historyPage=ref(1),historyPages=ref(1),historyTotal=ref(0),historyLoading=ref(false),historyError=ref("");
const grants=computed(()=>props.realm==="admin"?["*"]:reseller.session?.scopes??[]);
const canCreate=computed(()=>props.realm==="admin"?staff.can("resellers","manage"):reseller.can("team","create"));
const canUpdate=computed(()=>props.realm==="admin"?staff.can("resellers","manage"):reseller.can("team","update"));
const canReset=computed(()=>props.realm==="admin"?staff.can("resellers","manage"):reseller.can("team","manage"));
let readVersion=0, selectionVersion=0,historyVersion=0;
async function load():Promise<void>{const version=++readVersion;loading.value=true;error.value="";try{const result=await request<Page<ResellerAccount>>(`${base.value}?${query({page:page.value,q:q.value})}`);if(version!==readVersion)return;rows.value=result.data;pages.value=result.meta.pager?.total_pages??1;total.value=result.meta.pager?.total_items??0;}catch(cause){if(version===readVersion)error.value=cause instanceof Error?cause.message:t("resellerTeam.operationFailed");}finally{if(version===readVersion)loading.value=false;}}
async function loadCatalog():Promise<void>{try{catalog.value=await item<StaffScopeCatalog>(props.realm==="admin"?"/v1/admin/resellers/scope-catalog":"/v1/reseller/accounts/scope-catalog");}catch(cause){error.value=cause instanceof Error?cause.message:t("resellerTeam.operationFailed");}}
async function loadHistory():Promise<void>{const row=selected.value;if(!row)return;const version=++historyVersion;historyLoading.value=true;historyError.value="";try{const result=await request<Page<ResellerAccountChange>>(`${base.value}/${row.id}/history?${query({page:historyPage.value})}`);if(version!==historyVersion||selected.value?.id!==row.id)return;history.value=result.data;historyPages.value=result.meta.pager?.total_pages??1;historyTotal.value=result.meta.pager?.total_items??0;}catch(cause){if(version===historyVersion)historyError.value=cause instanceof Error?cause.message:t("resellerTeam.operationFailed");}finally{if(version===historyVersion)historyLoading.value=false;}}
async function select(row:ResellerAccount,preserve=false):Promise<void>{if(busy.value)return;const version=++selectionVersion;error.value="";try{const fresh=await item<ResellerAccount>(`${base.value}/${row.id}`);if(version!==selectionVersion)return;const same=selected.value?.id===row.id;selected.value=fresh;if(!preserve||!same){scopes.value=[...fresh.scopes];active.value=fresh.is_active;reason.value="";password.value="";passwordReason.value="";}history.value=[];historyPage.value=1;void loadHistory();}catch(cause){if(version===selectionVersion)error.value=cause instanceof Error?cause.message:t("resellerTeam.operationFailed");}}
async function refreshSelf(row:ResellerAccount):Promise<void>{if(props.realm==="reseller"&&row.id===reseller.session?.account_id)await reseller.restore();}
async function create():Promise<void>{if(busy.value||!canCreate.value||newActive.value==="")return;busy.value=true;error.value="";notice.value="";try{const row=await item<ResellerAccount>(base.value,"POST",{username:username.value,password:newPassword.value,scopes:newScopes.value,is_active:newActive.value==="true"});username.value="";newPassword.value="";newScopes.value=[];newActive.value="";selected.value=row;scopes.value=[...row.scopes];active.value=row.is_active;reason.value="";password.value="";passwordReason.value="";historyPage.value=1;createOpen.value=false;notice.value=t("resellerTeam.created");await Promise.all([load(),loadHistory()]);}catch(cause){error.value=cause instanceof Error?cause.message:t("resellerTeam.operationFailed");}finally{busy.value=false;}}
async function save():Promise<void>{const row=selected.value;if(!row||busy.value||!canUpdate.value)return;busy.value=true;error.value="";notice.value="";try{const fresh=await item<ResellerAccount>(`${base.value}/${row.id}`,"PUT",{expected_revision:row.revision,is_active:active.value,scopes:scopes.value,reason:reason.value});selected.value=fresh;reason.value="";notice.value=t("resellerTeam.accessSaved");await Promise.all([load(),loadHistory()]);await refreshSelf(fresh);}catch(cause){error.value=cause instanceof Error?cause.message:t("resellerTeam.operationFailed");}finally{busy.value=false;}}
async function reset():Promise<void>{const row=selected.value;if(!row||busy.value||!canReset.value)return;busy.value=true;error.value="";notice.value="";try{const fresh=await item<ResellerAccount>(`${base.value}/${row.id}/password`,"PUT",{expected_revision:row.revision,password:password.value,reason:passwordReason.value});selected.value=fresh;password.value="";passwordReason.value="";notice.value=t("resellerTeam.passwordChanged");await Promise.all([load(),loadHistory()]);await refreshSelf(fresh);}catch(cause){error.value=cause instanceof Error?cause.message:t("resellerTeam.operationFailed");}finally{busy.value=false;}}
const actionLabels=computed<Record<ResellerAccountChange["action"],string>>(()=>({create:t("resellerTeam.actionCreate"),access:t("resellerTeam.actionAccess"),password:t("resellerTeam.actionPassword")}));
watch(q,()=>{page.value=1;void load();});onMounted(()=>{void load();void loadCatalog();});
const createOpen=ref(false);
</script>
<template><button v-if="canCreate" class="btn" :disabled="busy" @click="createOpen=true">{{t('resellerTeam.createButton')}}</button>
  <p v-if="error" class="message error" role="alert">{{error}} <button class="btn small secondary" :disabled="busy" @click="load();loadCatalog()">{{t('resellerTeam.retry')}}</button></p><p v-if="notice" class="message" role="status">{{notice}}</p>
  <div :class="{split:!!selected}"><section class="card"><div class="card-pad"><label class="field"><span>{{t('resellerTeam.searchUsername')}}</span><input v-model="q" maxlength="120"/></label></div><div class="table-wrap"><table class="data-table"><thead><tr><th>{{t('resellerTeam.username')}}</th><th>{{t('resellerTeam.status')}}</th><th>{{t('resellerTeam.revision')}}</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id" tabindex="0" :class="{'selected-row':selected?.id===row.id}" @click="select(row)" @keydown.enter="select(row)"><td dir="ltr">{{row.username}}</td><td>{{row.is_active?t('resellerTeam.active'):t('resellerTeam.inactive')}}</td><td>{{faNumber(row.revision)}}</td></tr></tbody></table><p v-if="loading" class="empty">{{t('resellerTeam.loading')}}</p><p v-else-if="!rows.length&&!error" class="empty">{{t('resellerTeam.empty')}}</p></div><div class="pager"><button :disabled="page<=1||loading||busy" @click="page--;load()">‹</button><span>{{faNumber(page)}} · {{faNumber(total)}} {{t('resellerTeam.memberCount')}}</span><button :disabled="page>=pages||loading||busy" @click="page++;load()">›</button></div></section>
  <div class="stack"><section v-if="selected" class="card card-pad"><h2>{{selected.username}}</h2><p>{{t('resellerTeam.revision')}} {{faNumber(selected.revision)}} · {{selected.is_active?t('resellerTeam.active'):t('resellerTeam.inactive')}}</p><form v-if="canUpdate" class="form-grid" @submit.prevent="save"><label class="check-row"><input v-model="active" type="checkbox" :disabled="busy"/>{{t('resellerTeam.accountEnabled')}}</label><StaffScopeEditor v-model="scopes" :catalog="catalog" :grants="grants" :owner-label="t('resellerTeam.ownerLabel')" :disabled="busy"/><label class="field"><span>{{t('resellerTeam.accessReason')}}</span><input v-model="reason" minlength="3" maxlength="250" required :disabled="busy"/></label><button class="btn" :disabled="busy||!catalog||reason.trim().length<3">{{t('resellerTeam.saveAccess')}}</button></form><StaffScopeEditor v-else :model-value="selected.scopes" :catalog="catalog" :grants="[]" disabled :owner-label="t('resellerTeam.ownerLabel')"/><button class="btn secondary" :disabled="busy" @click="select(selected,true)">{{t('resellerTeam.refreshDraft')}}</button><p class="hint-box">{{t('resellerTeam.refreshHint')}}</p><form v-if="canReset" class="form-grid" @submit.prevent="reset"><label class="field"><span>{{t('resellerTeam.newPassword')}}</span><input v-model="password" type="password" minlength="8" maxlength="256" autocomplete="new-password" required :disabled="busy"/></label><label class="field"><span>{{t('resellerTeam.passwordReason')}}</span><input v-model="passwordReason" minlength="3" maxlength="250" required :disabled="busy"/></label><button class="btn secondary" :disabled="busy||password.length<8||passwordReason.trim().length<3">{{t('resellerTeam.changePassword')}}</button></form><h3>{{t('resellerTeam.history')}}</h3><p v-if="historyError" class="message error">{{historyError}} <button class="btn secondary" @click="loadHistory">{{t('resellerTeam.retry')}}</button></p><p v-if="historyLoading">{{t('resellerTeam.loading')}}</p><details v-for="change in history" :key="change.id"><summary>{{actionLabels[change.action]}} · {{t('resellerTeam.revision')}} {{faNumber(change.revision)}} · {{change.reason}}</summary><p>{{date(change.created_at)}} · {{change.is_active?t('resellerTeam.active'):t('resellerTeam.inactive')}} · {{change.staff_id!==null?t('resellerTeam.staffMember',{id:faNumber(change.staff_id)}):t('resellerTeam.resellerMember',{id:faNumber(change.actor_account_id??0)})}}</p><StaffScopeEditor :model-value="change.scopes" :catalog="catalog" :grants="['*']" :owner-label="t('resellerTeam.ownerLabel')" disabled/></details><div class="pager"><button :disabled="historyPage<=1||historyLoading" @click="historyPage--;loadHistory()">‹</button><span>{{faNumber(historyPage)}} · {{faNumber(historyTotal)}} {{t('resellerTeam.changes')}}</span><button :disabled="historyPage>=historyPages||historyLoading" @click="historyPage++;loadHistory()">›</button></div></section>
  <Modal v-if="canCreate" v-model="createOpen" :title="t('resellerTeam.createTitle')" :busy="busy" wide><p v-if="error" class="message error" role="alert">{{error}}</p><form class="form-grid" @submit.prevent="create"><label class="field"><span>{{t('resellerTeam.username')}}</span><input v-model="username" minlength="3" maxlength="64" pattern="[a-z0-9_.-]+" dir="ltr" required :disabled="busy"/></label><label class="field"><span>{{t('resellerTeam.password')}}</span><input v-model="newPassword" type="password" minlength="8" maxlength="256" autocomplete="new-password" required :disabled="busy"/></label><label class="field"><span>{{t('resellerTeam.initialStatus')}}</span><select  :aria-label="t('resellerTeam.initialStatus')" v-model="newActive" required :disabled="busy"><option value="" disabled>{{t('resellerTeam.selectOption')}}</option><option value="true">{{t('resellerTeam.active')}}</option><option value="false">{{t('resellerTeam.inactive')}}</option></select></label><StaffScopeEditor v-model="newScopes" :catalog="catalog" :grants="grants" :owner-label="t('resellerTeam.ownerLabel')" :disabled="busy"/><button class="btn" :disabled="busy||!catalog||newActive===''||newPassword.length<8">{{t('resellerTeam.createMember')}}</button></form></Modal></div></div>
</template>
<style scoped>details{padding:12px 0;border-bottom:1px solid var(--line)}summary{cursor:pointer}</style>
